  settings: { title: 'Impostazioni notifiche', body: 'Scegli quali notifiche email ricevere.', convTitle: 'Conversione completata', convBody: 'Notifica quando la conversione e pronta', weeklyTitle: 'Riassunto settimanale', weeklyBody: 'Email settimanale con statistiche', promoTitle: 'Email promozionali', promoBody: 'Novità e offerte speciali', savePrefs: 'Salva preferenze', saving: 'Salvataggio...', saved: 'Preferenze salvate', saveFail: 'Salvataggio fallito' },
