  profile: { title: 'Perfil', email: 'Email', update: 'Atualizar', updating: 'A guardar...', displayName: 'Nome público', yourName: 'O seu nome', save: 'Guardar', saving: 'A guardar...', plan: 'Plano', memberSince: 'Membro desde', totalConv: 'Conversões totais', bonusCreditsLabel: 'Créditos bonus', bonusCreditsValue: '{{count}} conversões extra/dia', dangerZone: 'Zona perigosa', deleteBtn: 'Eliminar conta', deleteWarn: 'Eliminação permanente. Não reversivel.', deleteYes: 'Sim, eliminar conta', cancel: 'Cancelar', profileUpdated: 'Perfil atualizado', updateFail: 'Falha ao atualizar', emailUpdated: 'Email atualizado', emailFail: 'Falha ao atualizar email', accountDeleted: 'Conta eliminada', deleteFail: 'Falha ao eliminar', errorGeneric: 'Erro', changePassword: "Alterar palavra-passe", currentPassword: "Palavra-passe atual", newPassword: "Nova palavra-passe", confirmNewPassword: "Confirmar nova palavra-passe", changing: "A alterar...", forgotPasswordPrompt: "Esqueceu a palavra-passe atual? Redefinir por email", sendResetLink: "Enviar link de redefinição", changeFailed: "Não foi possível alterar a palavra-passe", passwordChanged: 'Palavra-passe alterada', resetLinkSent: 'Link de redefinição enviado — verifique a sua caixa de entrada' },
  settings: { title: 'Definicoes de notificação', body: 'Escolha que notificações receber.', convTitle: 'Conversão concluida', convBody: 'Notificar quando a conversão terminar', weeklyTitle: 'Resumo semanal', weeklyBody: 'Email semanal com estatisticas', promoTitle: 'Emails promocionais', promoBody: 'Novidades e ofertas especiais', savePrefs: 'Guardar', saving: 'A guardar...', saved: 'Preferências guardadas', saveFail: 'Falha ao guardar' },
  share: { text: 'Acabei de converter um ficheiro com {{brand}}!', whatsapp: 'Partilhar no WhatsApp', twitter: 'Partilhar no X', copy: 'Copiar link', linkCopied: 'Link copiado!' },
  shortcuts: { title: 'Atalhos de teclado', openPalette: 'Abrir palete de comandos', startConv: 'Iniciar conversão', closeDialog: 'Fechar dialogos', showShortcuts: 'Mostrar atalhos' },
