  settings: { title: 'Notificatie-instellingen', body: 'Kies welke e-mailmeldingen je wilt ontvangen.', convTitle: 'Conversie voltooid', convBody: 'Krijg een melding wanneer je conversie klaar is', weeklyTitle: 'Wekelijkse samenvatting', weeklyBody: 'Wekelijkse e-mail met statistieken', promoTitle: 'Promotionele e-mails', promoBody: 'Hoor over nieuwe functies en aanbiedingen', savePrefs: 'Voorkeuren opslaan', saving: 'Opslaan...', saved: 'Voorkeuren opgeslagen', saveFail: 'Opslaan mislukt' },
  share: { text: 'Ik heb net een bestand geconverteerd met {{brand}}!', whatsapp: 'Delen op WhatsApp', twitter: 'Delen op X', copy: 'Link kopieren', linkCopied: 'Link gekopieerd!' },
