    speechToText: { name: 'Vorbire în text', description: 'Transcrie fișiere audio (MP3, WAV, M4A) într-un fișier text editabil.' },
    autoSubtitle: { name: 'Generator automat de subtitrări', description: 'Generează subtitrări SRT din fișiere video (MP4, MOV, AVI) automat din pista audio.' },
